insert into public.site_settings select * from jsonb_populate_recordset(null::public.site_settings, '[{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":1,"name":"Axel Püss","first_name":"Axel","location":"Estonia","headline":"I build websites, web apps and games, mostly the kind of things I''d actually want to use myself.","introduction":"Right now most of my days go into Casfyre, a freelance marketplace I''m building from scratch. Before the web stuff I spent a few years making games in Unreal Engine and C++, which is honestly where I learned most of what I know.","about":"Away from the screen I like hiking and being out in nature, and noticing the small stuff most people walk past. I also play the trombone and have a couple of small pets.\n\nI speak Estonian, English and German.","github_url":"https://github.com/AxeelDev/","twitter_url":"https://x.com/axeeeeeel__"}]'::jsonb) on conflict (id) do nothing;
insert into public.projects select * from jsonb_populate_recordset(null::public.projects, '[{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000001","thumbnail_url":"/projects/casfyre.jpg","thumbnail_alt":"The Casfyre homepage, with a large search asking what you need done","website_url":"https://www.casfyre.com/","source_url":null,"featured":true,"slug":"casfyre","title":"Casfyre","category":"Freelance marketplace","status":"active","listing":"selected","period":"2026 – now","summary":"A freelance marketplace I''m building from scratch. You find someone, talk it through, agree on the work, pay, and get it delivered, all in one place.","stack":["Next.js","Supabase","Stripe","Cloudflare"],"body":"## What it is\n\nCasfyre is a freelance marketplace for digital services, based in Estonia. Sellers publish service packages, buyers can post briefs, and you can message someone before ordering anything. There''s no platform fee on top of the price, and if a seller doesn''t accept an order within 24 hours, the buyer gets their money back.\n\n## The part I care about\n\nFreelance work usually falls apart in the boring places. Scope that was never written down, files spread over three different apps, nobody remembering what was agreed. So every order on Casfyre gets a Casefile: the scope, milestones, files, deliveries, revisions and decisions all stay attached to the work they belong to.\n\n## What I''m working on\n\nPretty much everything. Search over 400+ kinds of services, messaging, offers, fixed-price, milestone and hourly orders, payments, translations, the legal side. It''s the biggest thing I''ve built so far and it''s where most of my time goes right now.","published":true,"sort_order":0},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000002","thumbnail_url":"/projects/kanto.jpg","thumbnail_alt":"Kanto''s trending feed with threads from different communities, running locally with sample posts","website_url":null,"source_url":null,"featured":false,"slug":"kanto","title":"Kanto","category":"Forum","status":"archived","listing":"selected","period":"2026","summary":"A forum and imageboard mix. Communities like Reddit, anonymous posting like an imageboard, and a lot of moderation tools in between.","stack":["Astro","React","Drizzle","Postgres","Better Auth"],"body":"## What it is\n\nKanto is a forum where people make their own communities, each with its own rules, tags, layout and mod team. Threads and replies can be posted anonymously where the community allows it, and there''s voting, mentions, notifications, DMs, follows and a personalised feed on top of that.\n\n## How it went\n\nI built it in about five weeks, close to 500 commits. A lot of that time went into the stuff nobody sees: moderation and reporting, rate limiting, privacy and data deletion, encrypted DMs, permissions, and a full admin panel. There''s also a thing called micro-sites, where you can host a small single-file HTML/CSS/JS project in a sandbox right on the forum.\n\nIt''s not online at the moment, but it taught me a ton about building something where other people''s content and safety are part of the job.","published":true,"sort_order":1},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000003","thumbnail_url":"/projects/vaikusruum.jpg","thumbnail_alt":"The Vaikusruum homepage, with the name in a serif and the sun-like logo","website_url":"https://vaikusruum.ee/","source_url":"https://github.com/AxeelDev/Vaikusruum","featured":false,"slug":"vaikusruum","title":"Vaikusruum","category":"Client website","status":"active","listing":"selected","period":"2026","summary":"A website for a yoga teacher and musician. Calm on the outside, and she can change everything on it herself.","stack":["Next.js","Supabase","Vercel"],"body":"## What it is\n\nVaikusruum is an Estonian site for kundalini yoga, soft yoga and gong sessions. It has pages for the classes, private lessons, an FAQ, contact and feedback forms, and an about page.\n\n## The part I care about\n\nThe person running it should never need me to change a sentence. So the whole site runs off its own admin panel, where she can edit texts, photos and even the typography without touching any code. I also spent a good amount of time on SEO, so the site actually shows up when people search for it or for the teacher behind it, without any fake filler pages.","published":true,"sort_order":2},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000004","thumbnail_url":"/projects/the-last-customer.jpg","thumbnail_alt":"A dark gas station at night in The Last Customer, with the choice to explore or go to work","website_url":"https://store.steampowered.com/app/3249630/The_Last_Customer","source_url":null,"featured":false,"slug":"the-last-customer","title":"The Last Customer","category":"Horror game","status":"archived","listing":"selected","period":"2024","summary":"A survival horror game on Steam about a gas station clerk whose customers aren''t quite human. My first big project.","stack":["Unreal Engine 5"],"body":"## The game\n\nYou work night shifts at a gas station. Your friend goes missing, and finding him takes you through liminal spaces, puzzles, and things that are pretending to be customers. It came out on Steam in October 2024.\n\n## Honestly\n\nIt was my first big project, and I worked on it for about half a year. It''s rough in a lot of places and anything I''d make now would be way better. But that''s kind of the point. It''s where I actually learned game development: enemies, puzzles, choices, menus, lighting, and then the whole process of packaging a game and getting it released on Steam. Pretty much every mistake I made on it taught me something I still use.","published":true,"sort_order":3},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000005","thumbnail_url":null,"thumbnail_alt":"","website_url":null,"source_url":null,"featured":false,"slug":"casmine","title":"Casmine","category":"Voxel game","status":"active","listing":"small","period":"2026 – now","summary":"A voxel survival game going for the look and feel of Minecraft on the Xbox 360. Very early, mostly engine and world stuff so far.","stack":["Godot","Voxel Tools"],"body":"## The project\n\nCasmine is a voxel survival game I''m building in Godot. The goal is the feel of the old Xbox 360 edition of Minecraft: the light, the colours, the menus, the split-screen nights.\n\nIt''s very early. Right now it''s mostly world generation, rendering and the foundations for multiplayer, so there isn''t much to show yet.","published":true,"sort_order":4},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000006","thumbnail_url":"/projects/snaibo.jpg","thumbnail_alt":"The Snaibo code editor with a short script that repeats a hello world","website_url":null,"source_url":null,"featured":false,"slug":"snaibo","title":"Snaibo","category":"Scripting language","status":"experiment","listing":"small","period":"2025","summary":"A tiny scripting language. A text parser in C++ that runs .snaibo files with statements I made up myself.","stack":["C++"],"body":"Snaibo is a small project where I wrote a simple text parser in C++. I can add my own statements with different parameters, and then you can write .snaibo files and run them in a little code editor. It''s unfinished, but it was a fun way to learn how a language actually gets read and run.","published":true,"sort_order":5},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000007","thumbnail_url":"/projects/flappy-vhs.jpg","thumbnail_alt":"A small bird flying between green pipes with a VHS filter over everything","website_url":"https://www.youtube.com/watch?v=xMnPQxotlio","source_url":null,"featured":false,"slug":"flappy-vhs","title":"Flappy VHS","category":"Arcade game","status":"archived","listing":"small","period":"2025","summary":"Flappy Bird, but on an old VHS tape. Made in a single day, just to see what I could pull off in one.","stack":["Unreal Engine 5"],"body":"A one-day project. I made it on my own, with a few textures and assets borrowed from Sketchfab, just to show what I can make in a day. Difficulty levels, a high score, and a VHS look over everything. I don''t really plan to continue it.","published":true,"sort_order":6},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000008","thumbnail_url":"/projects/invert-nest.jpg","thumbnail_alt":"The Invert Nest homepage with featured pet products","website_url":null,"source_url":null,"featured":false,"slug":"invert-nest","title":"Invert Nest","category":"Webshop","status":"archived","listing":"small","period":"2025","summary":"A local webshop for pet supplies, mostly for invertebrates. It didn''t really catch on, and it''s offline now.","stack":["HTML","CSS","JavaScript"],"body":"Invert Nest was a webshop I made for my area, for animal supplies and mainly pet invertebrate supplies. I could add products dynamically and people could order them. All raw HTML, CSS and JavaScript. It didn''t catch on as well as I hoped, so it''s not running anymore.","published":true,"sort_order":7},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000009","thumbnail_url":"/projects/jeopardy.jpg","thumbnail_alt":"A Jeopardy board with four themes and point values from 100 to 500","website_url":null,"source_url":null,"featured":false,"slug":"jeopardy","title":"Jeopardy","category":"Party game","status":"archived","listing":"small","period":"2025","summary":"A Jeopardy game with its own editor, so you can make your own boards and play them with friends. Built in a day.","stack":["Unreal Engine 5","C++"],"body":"A simple Jeopardy game I made in a single day. You can make your own boards in the built-in editor and then play them with teams. Everything in it is built by me. It doesn''t save boards to a file yet, which is the obvious next thing if I come back to it.","published":true,"sort_order":8},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000010","thumbnail_url":"/projects/plus-one-speed.jpg","thumbnail_alt":"A character standing in front of colourful doors in a Door of Fortune minigame","website_url":null,"source_url":null,"featured":false,"slug":"plus-one-speed-per-second","title":"+1 Speed Per Second","category":"Game prototype","status":"experiment","listing":"small","period":"2025","summary":"Every second you get a bit faster. A remake of a Roblox game idea, made to try out different mechanics.","stack":["Unreal Engine 5"],"body":"A scrap project to try making different mechanics, based on a Roblox game that works kind of the same way. Every second you get +1 speed, and you can play minigames I built in there to win trophies, which give you even more speed per second.","published":true,"sort_order":9},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"10000000-0000-4000-8000-000000000011","thumbnail_url":"/projects/crops-vs-creeps.jpg","thumbnail_alt":"A checkered green lawn with plants defending against creeps","website_url":null,"source_url":null,"featured":false,"slug":"crops-vs-creeps","title":"Crops vs Creeps","category":"Tower defence","status":"archived","listing":"small","period":"","summary":"Basically a Plants vs Zombies clone I made from scratch for fun.","stack":["Game dev"],"body":"Another small side project I made for fun. It''s basically a Plants vs Zombies clone, built from scratch with some free assets I found. It was a really fun one to make.","published":true,"sort_order":10}]'::jsonb) on conflict (id) do nothing;
insert into public.posts select * from jsonb_populate_recordset(null::public.posts, '[{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"20000000-0000-4000-8000-000000000001","slug":"a-place-for-project-notes","title":"A place for project notes","excerpt":"Small decisions, things I’ve learned, and what I’m making next.","body":"This is a sample entry, here so you can try the writing section before connecting a database. Replace it with your own words in the editor.\n\n## A few things this space can hold\n\n- Progress on an ongoing project\n- An interesting problem and how you solved it\n- Something you tried that didn’t work\n\nYou can use **Markdown**, add links, write code, and include images.\n\n```ts\nconst smallThings = [\"build\", \"notice\", \"improve\"];\n```\n\nA post can stay as a draft until you’re ready to publish it.","cover_url":null,"cover_alt":"","tags":["Sample entry"],"published":false,"published_at":"2026-09-26T12:00:00Z"},{"created_at":"2026-09-26T12:00:00Z","updated_at":"2026-09-26T12:00:00Z","id":"20000000-0000-4000-8000-000000000002","slug":"notes-from-the-workbench","title":"Notes from the workbench","excerpt":"A second sample entry for shorter updates and unfinished ideas.","body":"This is another sample entry. It shows how shorter notes sit alongside longer articles.\n\nThere doesn’t have to be a grand conclusion. Sometimes an observation is enough.\n\n> Replace these sample posts with your own writing, then publish them when they’re ready.","cover_url":null,"cover_alt":"","tags":["Sample entry"],"published":false,"published_at":"2026-09-20T12:00:00Z"}]'::jsonb) on conflict (id) do nothing;
